steps.run:
set -euo pipefail

findings=$(mktemp "$RUNNER_TEMP/previous-findings.XXXXXX")
sha=""
load_previous() {
  local reviews threads ids
  reviews=$(gh api "repos/$GITHUB_REPOSITORY/pulls/$PR_NUMBER/reviews" --paginate --slurp |
    jq -ce '[.[][]
      | select(.user.login == "github-actions[bot]")
      | select((.body // "") | contains("<!-- gcx-claude-review:"))]') || return 1
  [ "$(jq 'length' <<< "$reviews")" -gt 0 ] || return 0
  ids=$(jq '[.[] | {key: (.id | tostring), value: .commit_id[:12]}] | from_entries' <<< "$reviews") || return 1
  threads=$(gh api graphql --paginate --slurp \
    -f owner="${GITHUB_REPOSITORY%/*}" -f name="${GITHUB_REPOSITORY#*/}" \
    -F number="$PR_NUMBER" -f query='
      query($owner: String!, $name: String!, $number: Int!, $endCursor: String) {
        repository(owner: $owner, name: $name) {
          pullRequest(number: $number) {
            reviewThreads(first: 100, after: $endCursor) {
              pageInfo { hasNextPage endCursor }
              nodes {
                isResolved isOutdated path line originalLine
                comments(first: 1) {
                  nodes { body pullRequestReview { databaseId } }
                }
              }
            }
          }
        }
      }') || return 1
  jq -r --argjson ids "$ids" '
    def trim: gsub("^\\s+|\\s+$"; "");
    [.[] | .data.repository.pullRequest.reviewThreads.nodes[]
      | select(.isResolved == false)
      | .comments.nodes[0] as $comment
      | ($ids[($comment.pullRequestReview.databaseId // "" | tostring)]) as $commit
      | select($commit != null)
      | ($comment.body | gsub("\r|<!--|-->"; "") | split("\n")
          | map(trim | select(length > 0)) | .[0] // "" | .[:200]) as $body
      | "- \(.path):\(.line // .originalLine // "?") (review of \($commit)) \(if .isOutdated then "[outdated] " else "" end)\($body)"]
    | .[:30][]
  ' <<< "$threads" > "$findings" || return 1
  sha=$(jq -r 'max_by(.submitted_at).commit_id // empty' <<< "$reviews") || return 1
}

if ! load_previous; then
  echo "::warning::Could not read previous Claude reviews; continuing with a full review."
  sha=""
  : > "$findings"
fi
delim="EOF_$(openssl rand -hex 16)"
{
  echo "sha=$sha"
  echo "findings<<$delim"
  cat "$findings"
  echo "$delim"
} >> "$GITHUB_OUTPUT"
